class E {
public:
    E(); // Default constructor
    explicit E(typename traits::result_type seed); // Seeded constructor
    explicit E(const seed_seq& s); // Seed sequence constructor
    void seed(); // Reset to default state
    void seed(typename traits::result_type s); // Seed with specific value
    void seed(const seed_seq& s); // Seed with seed sequence
    typename traits::result_type operator()(); // Generate next random number
    void discard(unsigned long z); // Advance state by z steps
    bool operator==(const E& other) const; // Equality comparison
    bool operator!=(const E& other) const; // Inequality comparison
    friend std::ostream& operator<<(std::ostream& os, const E& e); // Output state
    friend std::istream& operator>>(std::istream& is, E& e); // Input state
};

